// HostServer is the server API for Host service.
// All implementations must embed UnimplementedHostServer
// for forward compatibility.
type HostServer interface {
	// Accounts: the camera's users, which can change while it runs.
	AccountsList(context.Context, *AccountsListRequest) (*AccountsListResponse, error)
	// State
	StateGet(context.Context, *StateGetRequest) (*StateGetResponse, error)
	StateList(context.Context, *StateListRequest) (*StateListResponse, error)
	StateSet(context.Context, *StateSetRequest) (*StateSetResponse, error)
	StateCanon(context.Context, *StateGetRequest) (*StateGetResponse, error)
	StateWatch(*StateWatchRequest, grpc.ServerStreamingServer[StateChanges]) error
	// Events
	EventEmit(context.Context, *EventEmitRequest) (*EventEmitResponse, error)
	EventSubscribe(*EventSubscribeRequest, grpc.ServerStreamingServer[Dispatch]) error
	DeliveryReport(context.Context, *DeliveryReportRequest) (*DeliveryReportResponse, error)
	// The targets the camera delivers a transport to now, for engines that
	// keep connections open to them (an MQTT client and its broker).
	EventTargets(context.Context, *EventSubscribeRequest) (*EventTargetsResponse, error)
	// Media
	MediaStreams(context.Context, *MediaStreamsRequest) (*MediaStreamsResponse, error)
	MediaSnapshot(context.Context, *MediaSnapshotRequest) (*MediaSnapshotResponse, error)
	// Templates
	TemplateRender(context.Context, *TemplateRenderRequest) (*TemplateRenderResponse, error)
	// Files: the recordings on the camera's SD card or NAS share, which the
	// host records; engines search and read them.
	FileStatus(context.Context, *FileStatusRequest) (*StorageStatus, error)
	FileFind(context.Context, *FileFindRequest) (*FileFindResponse, error)
	FileGet(*FileGetRequest, grpc.ServerStreamingServer[FileChunk]) error
	// Faults: the status every request to an engine instance gets while an
	// injected fault is on; 0 when none.
	FaultStatus(context.Context, *FaultStatusRequest) (*FaultStatusResponse, error)
	// Telemetry
	Log(context.Context, *LogRequest) (*LogResponse, error)
	RequestStat(context.Context, *RequestStatRequest) (*RequestStatResponse, error)
	Gap(context.Context, *GapRequest) (*GapResponse, error)
	Client(context.Context, *ClientRequest) (*ClientResponse, error)
	mustEmbedUnimplementedHostServer()
}

